  var cause = original
  (inComp.forall( 
  	d => d match {
  	  case SFnDecl(_,h,_,_,_) => if (h.getMods().isAbstract()) {
  	    val b = inAPI.exists(r => equalMember(d,r))
  	    if (b) true else { cause = addMessage(cause, "Asbtract method " + h.getName() + " @ " + NodeUtil.getSpan(d) + " is not declared in the API") ; false }
  	  }  else true
  	  case _ => true
  	}

  ),cause)
}                  	



